function toggleHabit(id: string, date: Date) {
  setHabits(curr =>
    curr.map(h => {
      if (h.id !== id) return h

      const alreadyDone = h.completions.some(c => isSameDay(c, date))
      const completions = alreadyDone
        ? h.completions.filter(c => !isSameDay(c, date))
        : [...h.completions, date]

      return { ...h, completions }
    }),
  )
}

